{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.pronk_sku_profitability_report as with all_sku_dates as ( SELECT DISTINCT upper(SKU) sku, c.date_day, d.final_marketplace marketplace, FROM pronk-wh.maplemonk.pronk_SALES_CONSOLIDATED d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2024-01-01\', CURRENT_DATE())) AS date_day ) AS c ) select distinct fi.sku, fi.date_day, fi.marketplace, maplemonk.get_category(ifnull(fi.sku,\'\')) as Product_Category, maplemonk.get_sub_category(ifnull(fi.sku,\'\')) as Product_Sub_Category, maplemonk.get_color(ifnull(fi.sku,\'\')) as Product_Colour, maplemonk.get_size(ifnull(fi.sku,\'\')) as Product_Size, maplemonk.get_dt_code(ifnull(fi.sku,\'\')) as Product_DT_Code, maplemonk.get_gender(ifnull(fi.sku,\'\')) as Gender, total_sales, total_quantity, total_orders, i.avg_grn_cost as grn_cost, case when (maplemonk.get_dt_code(ifnull(fi.sku,\'\')) is null or maplemonk.get_dt_code(ifnull(fi.sku,\'\')) = \'NA\') then i.avg_grn_cost else (i.avg_grn_cost + 60) end as avg_grn_cost from all_sku_dates FI left join (select upper(sku) sku, date(order_date) date, upper(final_marketplace) as marketplace, sum(ifnull(selling_price,0)) as total_sales, sum(ifnull(quantity,0)) as total_quantity, count(distinct order_id) as total_orders from maplemonk.pronk_sales_consolidated where rto_flag = 0 and dto_flag = 0 and (order_status is null or not(order_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) and (oms_order_status is null or not(oms_order_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) and (final_shipping_status is null or not(final_shipping_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) group by 1,2,3 ) s on s.sku = fi.sku and date(s.date) = date(fi.date_day) and lower(s.marketplace) = lower(fi.marketplace) left join (select upper(maplemonk.get_sku_without_dt_code(ifnull(trim(sku),\'\'))) as sku, avg(cast(grn_cost as float64)) as avg_grn_cost from maplemonk.Easyecom_full_inventory_report group by 1 qualify row_number() over (partition by sku order by 1)=1 )i on lower(i.sku) = lower(maplemonk.get_sku_without_dt_code(fi.sku)) ; CREATE OR REPLACE TABLE maplemonk.pronk_daily_profitability_report AS WITH base_dates AS ( SELECT DISTINCT DATE(order_date) AS date_day, UPPER(final_marketplace) AS marketplace FROM maplemonk.pronk_sales_consolidated ), sales_data AS ( SELECT DATE(order_date) AS date_day, UPPER(final_marketplace) AS marketplace, SUM(IFNULL(selling_price,0)) AS total_sales, SUM(IFNULL(quantity,0)) AS total_quantity, COUNT(DISTINCT order_id) AS total_orders FROM maplemonk.pronk_sales_consolidated WHERE rto_flag = 0 AND dto_flag = 0 AND (order_status IS NULL OR NOT(order_status LIKE ANY (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) AND (oms_order_status IS NULL OR NOT(oms_order_status LIKE ANY (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) AND (final_shipping_status IS NULL OR NOT(final_shipping_status LIKE ANY (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) GROUP BY 1,2 ), grn_cost_daily AS ( SELECT DATE(s.order_date) AS date_day, UPPER(s.final_marketplace) AS marketplace, SUM(IFNULL(i.avg_grn_cost,0) * IFNULL(s.quantity,0)) AS grn_cost, SUM( IFNULL( CASE WHEN maplemonk.get_dt_code(IFNULL(s.sku,\'\')) IS NULL OR maplemonk.get_dt_code(IFNULL(s.sku,\'\')) = \'NA\' THEN i.avg_grn_cost ELSE (i.avg_grn_cost + 60) END,0 ) * IFNULL(s.quantity,0) ) AS avg_grn_cost FROM maplemonk.pronk_sales_consolidated s LEFT JOIN ( SELECT UPPER(maplemonk.get_sku_without_dt_code(IFNULL(TRIM(sku),\'\'))) AS sku, AVG(CAST(grn_cost AS FLOAT64)) AS avg_grn_cost FROM maplemonk.Easyecom_full_inventory_report GROUP BY 1 ) i ON LOWER(i.sku) = LOWER(maplemonk.get_sku_without_dt_code(s.sku)) WHERE s.rto_flag = 0 AND s.dto_flag = 0 GROUP BY 1,2 ), marketing AS ( SELECT date, CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\', \'%google%\') THEN \'WEBSITE\' WHEN LOWER(channel) LIKE ANY (\'%amazon%\') THEN \'AMAZON\' WHEN LOWER(channel) LIKE \'%flipkart%\' THEN \'FLIPKART\' WHEN LOWER(channel) LIKE \'%myntra%\' THEN \'MYNTRA\' ELSE UPPER(channel) END AS marketplace, SUM(IFNULL(spend,0)) AS spend FROM pronk-wh.maplemonk.pronk_MARKETING_CONSOLIDATED GROUP BY 1,2 ) SELECT b.date_day, b.marketplace, IFNULL(s.total_sales,0) AS total_sales, IFNULL(s.total_quantity,0) AS total_quantity, IFNULL(s.total_orders,0) AS total_orders, IFNULL(g.grn_cost,0) AS grn_cost, IFNULL(g.avg_grn_cost,0) AS avg_grn_cost, IFNULL(m.spend,0) AS adv_spends FROM base_dates b LEFT JOIN sales_data s ON b.date_day = s.date_day AND LOWER(b.marketplace) = LOWER(s.marketplace) LEFT JOIN grn_cost_daily g ON b.date_day = g.date_day AND LOWER(b.marketplace) = LOWER(g.marketplace) LEFT JOIN marketing m ON b.date_day = m.date AND LOWER(b.marketplace) = LOWER(m.marketplace) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            